#!/usr/bin/env node
/**
 * Reverse of summary-to-docx.js: reads a .docx generated by that script (or
 * matching its structure — Heading2 for "N) Title", Heading3 for "A. Title"
 * with numbered/lettered bullets underneath) and reconstructs the V3
 * summary markdown convention: "## N) Title", "### A. Title",
 * top-level "- text" bullets, nested "  - ◦ text" bullets.
 *
 * Usage: node docx-to-summary-md.js <input.docx> <output.md>
 */
const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");
const os = require("os");

const [, , inPath, outPath] = process.argv;
if (!inPath || !outPath) {
  console.error("Usage: node docx-to-summary-md.js <input.docx> <output.md>");
  process.exit(1);
}

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "docx-extract-"));
execSync(`unzip -oq "${inPath}" -d "${tmpDir}"`);
const xml = fs.readFileSync(path.join(tmpDir, "word", "document.xml"), "utf8");

// numbering.xml: map numId -> abstractNumId -> level -> indent (to tell
// "bullets" level0/1 apart from "bulletsIndented" level0/1 by indent size)
let numToAbstract = {};
let abstractLevelIndent = {}; // abstractNumId -> level -> indent left
try {
  const numberingXml = fs.readFileSync(path.join(tmpDir, "word", "numbering.xml"), "utf8");
  for (const m of numberingXml.matchAll(/<w:num w:numId="(\d+)"[^>]*>\s*<w:abstractNumId w:val="(\d+)"/g)) {
    numToAbstract[m[1]] = m[2];
  }
  for (const am of numberingXml.matchAll(/<w:abstractNum w:abstractNumId="(\d+)">([\s\S]*?)<\/w:abstractNum>/g)) {
    const id = am[1];
    abstractLevelIndent[id] = {};
    for (const lm of am[2].matchAll(/<w:lvl w:ilvl="(\d+)">[\s\S]*?w:left="(\d+)"/g)) {
      abstractLevelIndent[id][lm[1]] = parseInt(lm[2], 10);
    }
  }
} catch (e) {
  // no numbering.xml (no bullets in doc) — fine
}

function textOf(p) {
  return [...p.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)]
    .map((m) => m[1])
    .join("")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

function isBold(p) {
  return /<w:b\/>|<w:b w:val="(true|1)"/.test(p);
}

const paras = [...xml.matchAll(/<w:p\b[\s\S]*?<\/w:p>/g)].map((m) => m[0]);
const lines = [];

for (const p of paras) {
  const text = textOf(p).trim();
  if (!text) continue;

  let styleMatch = p.match(/w:pStyle w:val="(Heading[0-9])"/);
  const numIdMatch = p.match(/<w:numId w:val="(\d+)"\/>/);
  const ilvlMatch = p.match(/<w:ilvl w:val="(\d+)"\/>/);

  // Fallback for docs with no named paragraph styles at all (e.g. plain
  // text pasted into Word without applying Heading 2/3) — a paragraph
  // that ISN'T a bullet item, whose text matches our numbered/lettered
  // section-title pattern, is almost certainly meant to be that heading
  // level even though nothing in the XML says so structurally.
  if (!styleMatch && !numIdMatch) {
    if (/^\d+\)\s+\S/.test(text)) {
      styleMatch = [null, "Heading2"];
    } else if (/^[A-Z]\.\s+\S/.test(text)) {
      styleMatch = [null, "Heading3"];
    }
  }
  // bold-run detection: treat runs individually to rebuild **bold** markers
  const runs = [...p.matchAll(/<w:r>([\s\S]*?)<\/w:r>/g)].map((m) => m[1]);
  let rebuilt = "";
  for (const r of runs) {
    const t = [...r.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)].map((m) => m[1]).join("");
    if (!t) continue;
    const bold = /<w:b\/>|<w:b w:val="(true|1)"/.test(r);
    const decoded = t
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">");
    rebuilt += bold ? `**${decoded}**` : decoded;
  }
  const finalText = rebuilt || text;

  if (styleMatch === null && numIdMatch === null) {
    // plain paragraph text
    lines.push(finalText);
    lines.push("");
    continue;
  }

  if (styleMatch) {
    const level = styleMatch[1];
    if (level === "Heading2") {
      lines.push(`## ${finalText}`);
      lines.push("");
    } else if (level === "Heading3") {
      lines.push(`### ${finalText}`);
      lines.push("");
    } else {
      lines.push(finalText);
      lines.push("");
    }
    continue;
  }

  if (numIdMatch) {
    const numId = numIdMatch[1];
    const ilvl = ilvlMatch ? ilvlMatch[1] : "0";
    const abstractId = numToAbstract[numId];
    const indent = abstractId && abstractLevelIndent[abstractId]
      ? abstractLevelIndent[abstractId][ilvl]
      : undefined;
    // level 0 (top-level bullet under either bullets/bulletsIndented) -> "- text"
    // level 1 (nested) -> "  - ◦ text"
    if (ilvl === "0") {
      lines.push(`- ${finalText}`);
    } else {
      lines.push(`  - ◦ ${finalText}`);
    }
    continue;
  }
}

fs.writeFileSync(outPath, lines.join("\n").replace(/\n{3,}/g, "\n\n") + "\n");
fs.rmSync(tmpDir, { recursive: true, force: true });
console.log(`Extracted ${paras.length} paragraphs -> ${outPath}`);
